type Result struct {
	StatementId          *string
	RowCount             *int64
	IsTruncated          *bool
	StatementIdSignature *string
}

// Contains the result data of a single chunk when using `INLINE` disposition.
// When using `EXTERNAL_LINKS` disposition, the array `external_links` is used
// instead to provide URLs to the result data in cloud storage. Exactly one of
// these alternatives is used. (While the `external_links` array prepares the
// API to return multiple links in a single response. Currently only a single
// link is returned.).
type ResultData struct {
	ExternalLinks         []ExternalLink
	DataArray             []ListValue
	ChunkIndex            *int
	RowOffset             *int64
	RowCount              *int64
	ByteCount             *int64
	NextChunkIndex        *int
	NextChunkInternalLink *string
}

// The result manifest provides schema and metadata for the result set..
type ResultManifest struct {
	Format          Format
	Schema          *Schema
	TotalChunkCount *int
	Chunks          []ChunkInfo
	TotalRowCount   *int64
	TotalByteCount  *int64
	Truncated       *bool
}

type Schema struct {
	ColumnCount *int
	Columns     []ColumnInfo
}

type StatementResponse struct {
	StatementId *string
	Status      *StatementStatus
	Manifest    *ResultManifest
	Result      *ResultData
}

// The status response includes execution state and if relevant, error
// information..
type StatementStatus struct {
	State    StatementStatus_State
	Error    *DatabricksServiceExceptionProto
	SqlState *string
}

